class Solution {
public:
    int countPartitions(std::vector<int>& nums, int k) {
        long long MOD = 1e9 + 7;
        long long total = 0;
        for (int x : nums) total += x;
        if (total < 2LL * k) return 0;

        std::vector<long long> dp(k, 0);
        dp[0] = 1;
        for (int x : nums) {
            for (int s = k - 1; s >= x; --s) {
                dp[s] = (dp[s] + dp[s - x]) % MOD;
            }
        }
        long long bad = 0;
        for (int s = 0; s < k; ++s) bad = (bad + dp[s]) % MOD;
        bad = (bad * 2) % MOD;

        long long total_partitions = 1;
        for (size_t i = 0; i < nums.size(); ++i) total_partitions = (total_partitions * 2) % MOD;
        return (total_partitions - bad + MOD) % MOD;
    }
};

class Solution {
    public int countPartitions(int[] nums, int k) {
        long MOD = 1_000_000_007L;
        long total = 0;
        for (int x : nums) total += x;
        if (total < 2L * k) return 0;

        long[] dp = new long[k];
        dp[0] = 1;
        for (int x : nums) {
            for (int s = k - 1; s >= x; s--) {
                dp[s] = (dp[s] + dp[s - x]) % MOD;
            }
        }
        long bad = 0;
        for (int s = 0; s < k; s++) bad = (bad + dp[s]) % MOD;
        bad = (bad * 2) % MOD;

        long totalPartitions = 1;
        for (int i = 0; i < nums.length; i++) totalPartitions = (totalPartitions * 2) % MOD;
        return (int)((totalPartitions - bad + MOD) % MOD);
    }
}

var countPartitions = function(nums, k) {
    const MOD = 1000000007n;
    let total = 0n;
    for (const x of nums) total += BigInt(x);
    if (total < 2n * BigInt(k)) return 0;

    const dp = new Array(k).fill(0n);
    dp[0] = 1n;
    for (const x of nums) {
        for (let s = k - 1; s >= x; s--) {
            dp[s] = (dp[s] + dp[s - x]) % MOD;
        }
    }
    let bad = 0n;
    for (let s = 0; s < k; s++) bad = (bad + dp[s]) % MOD;
    bad = (bad * 2n) % MOD;

    let totalPartitions = 1n;
    for (let i = 0; i < nums.length; i++) totalPartitions = (totalPartitions * 2n) % MOD;
    return Number((totalPartitions - bad + MOD) % MOD);
};
